load bats-extra
load bats-jq

@test 'Create robot:at origin facing north' {
    #[[ $BATS_RUN_SKIPPED == "true" ]] || skip

    run jq -c -f robot-simulator.jq << 'END_INPUT'
      {
        "robot": {
          "position": {
            "x": 0,
            "y": 0
          },
          "direction": "north"
        }
      }
END_INPUT

    assert_success
    expected='{"position":{"x":0,"y":0},"direction":"north"}'
